effect.shader:
const int AMOSTRAS = 16;
const float TAU = 6.2831853;

/** Luminância ITU-R BT.709. */
float luma(vec3 c) {
    return dot(c, vec3(0.2126, 0.7152, 0.0722));
}

/** Só o que está acima do limiar, suavizado. */
vec3 apenasAsLuzes(vec3 c) {
    float L = luma(c);
    float f = smoothstep(threshold, threshold + 0.15, L);
    return c * f;
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 px = 1.0 / vec2(textureSize(inputImg, 0));

    // 16 amostras num círculo com raios diferentes por canal — as luzes de
    // cada canal ficam em círculos diferentes, as bordas do halo se separam.
    vec3 bloom = vec3(0.0);
    for (int i = 0; i < AMOSTRAS; i++) {
        float ang = TAU * (float(i) + 0.5) / float(AMOSTRAS);
        vec2 direcao = vec2(cos(ang), sin(ang));

        float raioR = radius * (1.0 + chromaticSpread * 0.5);
        float raioG = radius;
        float raioB = radius * (1.0 - chromaticSpread * 0.5);

        bloom.r += apenasAsLuzes(texture(inputImg, acScreenNorm + direcao * raioR * px).rgb).r;
        bloom.g += apenasAsLuzes(texture(inputImg, acScreenNorm + direcao * raioG * px).rgb).g;
        bloom.b += apenasAsLuzes(texture(inputImg, acScreenNorm + direcao * raioB * px).rgb).b;
    }
    bloom /= float(AMOSTRAS);

    // Mistura por adição com peso de intensidade; clampa pra não saturar branco liso.
    vec3 cor = original.rgb + bloom * intensity;
    cor = clamp(cor, 0.0, 1.0);

    fragColor = vec4(cor, original.a);
}
